package dev.kyrion.core.security

import org.springframework.beans.factory.annotation.Value
import org.springframework.http.HttpStatus
import org.springframework.stereotype.Component
import org.springframework.web.bind.annotation.ResponseStatus
import java.nio.file.Files
import java.nio.file.LinkOption.NOFOLLOW_LINKS
import java.nio.file.Path
import java.nio.file.attribute.PosixFilePermission
import java.security.MessageDigest
import java.time.Clock
import java.time.Duration

/** Installer-owned file; never generated by Core or returned through the API. */
@Component
class FirstOwnerBootstrap(
    @Value("\${kyrion.security.bootstrap-secret-file:}") private val secretFile: String,
    private val clock: Clock = Clock.systemUTC(),
) {
    private val attempts = LoginAttemptLimiter(clock)

    fun verify(provided: String?) {
        attempts.backoffFor("first-owner")?.let { throw LoginRateLimitedException(it.retryAfter(clock.instant())) }
        if (!valid(provided)) {
            attempts.recordFailure("first-owner")
            throw BootstrapForbiddenException()
        }
    }

    private fun valid(provided: String?): Boolean {
        if (provided == null || !provided.matches(Regex("[A-Za-z0-9_-]{43}")) || secretFile.isBlank()) return false
        return runCatching {
            val path = Path.of(secretFile)
            if (!Files.isRegularFile(path, NOFOLLOW_LINKS) || Files.size(path) > 128) return false
            if (Files.getFileStore(path).supportsFileAttributeView("posix")) {
                val forbidden = setOf(
                    PosixFilePermission.GROUP_READ, PosixFilePermission.GROUP_WRITE,
                    PosixFilePermission.GROUP_EXECUTE, PosixFilePermission.OTHERS_READ,
                    PosixFilePermission.OTHERS_WRITE, PosixFilePermission.OTHERS_EXECUTE
                )
                if (Files.getPosixFilePermissions(path).any { it in forbidden }) return false
            }
            val created = Files.getLastModifiedTime(path, NOFOLLOW_LINKS).toInstant()
            val age = Duration.between(created, clock.instant())
            if (age.isNegative || age > Duration.ofMinutes(30)) return false
            val expected = Files.readString(path).trim()
            expected.matches(Regex("[A-Za-z0-9_-]{43}")) && MessageDigest.isEqual(
                expected.toByteArray(Charsets.US_ASCII), provided.toByteArray(Charsets.US_ASCII),
            )
        }.getOrDefault(false)
    }
}

@ResponseStatus(HttpStatus.FORBIDDEN)
class BootstrapForbiddenException : RuntimeException()
